// Package tenant defines the identifier and the lifecycle of a tenant. It has no database code:
// identifiers are generated by the database.
package tenant

import (
	"encoding/hex"
	"errors"
)

// ID identifies a tenant. The zero value is "no tenant" and is never a valid tenant.
type ID [16]byte

// ErrInvalidID is returned by ParseID for anything but the canonical form of a non-zero UUID.
var ErrInvalidID = errors.New("tenant: invalid id")

// ParseID parses the canonical text form of a UUID: 36 characters, lower-case hexadecimal,
// hyphens at positions 8, 13, 18 and 23. Anything else, and the all-zero UUID, is ErrInvalidID.
func ParseID(s string) (ID, error) {
	var id ID
	if len(s) != 36 {
		return id, ErrInvalidID
	}
	raw := make([]byte, 0, 32)
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch i {
		case 8, 13, 18, 23:
			if c != '-' {
				return ID{}, ErrInvalidID
			}
			continue
		}
		if (c < '0' || c > '9') && (c < 'a' || c > 'f') {
			return ID{}, ErrInvalidID
		}
		raw = append(raw, c)
	}
	if _, err := hex.Decode(id[:], raw); err != nil {
		return ID{}, ErrInvalidID
	}
	if id.IsZero() {
		return ID{}, ErrInvalidID
	}
	return id, nil
}

// String returns the canonical text form.
func (id ID) String() string {
	h := hex.EncodeToString(id[:])
	return h[0:8] + "-" + h[8:12] + "-" + h[12:16] + "-" + h[16:20] + "-" + h[20:32]
}

// IsZero reports whether id is the zero value, "no tenant".
func (id ID) IsZero() bool { return id == ID{} }

// State is a lifecycle state of a tenant (TEN-09).
type State string

// The five states of a tenant.
const (
	StateProvisioning State = "provisioning"
	StateActive       State = "active"
	StateSuspended    State = "suspended"
	StateDeleting     State = "deleting"
	StateDeleted      State = "deleted"
)

// States returns the five states, in lifecycle order.
func States() []State {
	return []State{StateProvisioning, StateActive, StateSuspended, StateDeleting, StateDeleted}
}

// ParseState returns the state named s, and false when s is not exactly one of the five names.
func ParseState(s string) (State, bool) {
	for _, st := range States() {
		if string(st) == s {
			return st, true
		}
	}
	return "", false
}

// CanTransition reports whether a tenant may move from one state to the other. It is true only
// for the seven moves of the lifecycle; a state to itself is not a transition.
func CanTransition(from, to State) bool {
	switch from {
	case StateProvisioning:
		return to == StateActive || to == StateDeleting
	case StateActive:
		return to == StateSuspended || to == StateDeleting
	case StateSuspended:
		return to == StateActive || to == StateDeleting
	case StateDeleting:
		return to == StateDeleted
	}
	return false
}
